example.code:

public partial class PersonViewModel : INotifyPropertyChanged
{
    public PersonViewModel(IObservable<string> names) =>
        _fullNameHelper = names.ToProperty(this, x => x.FullName);

    public event PropertyChangedEventHandler? PropertyChanged;

    [ObservableAsProperty]
    public partial string FullName { get; }
}


_fullName = this.WhenAnyValue(x => x.FirstName, x => x.LastName, (first, last) => $"{first} {last}")
    .ToProperty(this, x => x.FullName);

public string FullName => _fullName.Value;

// The view is registered only as IViewFor<TodoViewModel> in the service locator.
object viewModel = new TodoViewModel();
var view = ViewLocator.GetCurrent().ResolveViewUnsafe(viewModel, contract: null);

// The view is registered only as IViewFor<TodoViewModel> in the service locator.
object viewModel = new TodoViewModel();
var view = ViewLocator.GetCurrent().ResolveViewUnsafe(viewModel);

member.remarks:
These methods allow fluent chains such as:
RxBindingBuilder.CreateReactiveUIBindingBuilder() .WithCoreServices() .BuildApp();
Because returns , these extension methods cast back to to continue chaining.

example.code:
var locator = new DefaultViewLocator();
locator.Map<TodoViewModel, TodoView>();

object viewModel = new TodoViewModel();
var view = locator.ResolveView(viewModel, contract: null); // a TodoView

AppLocator.CurrentMutable.Register<IViewFor<TodoViewModel>>(static () => new TodoView());

object viewModel = new TodoViewModel();
var view = new DefaultViewLocator().ResolveViewUnsafe(viewModel, contract: null); // a TodoView
